package app.gendragoon.cloudssd.mobile;
import android.app.*;
import android.content.*;
import android.content.pm.ServiceInfo;
import android.net.Uri;
import android.provider.OpenableColumns;
import android.database.Cursor;
import androidx.annotation.NonNull;
import androidx.core.app.NotificationCompat;
import androidx.documentfile.provider.DocumentFile;
import androidx.work.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.TimeUnit;
import org.json.*;

/** SAF owner selections -> pinned encrypted PNG protocol -> complete readback. */
public final class TransferWorker extends Worker implements CryptoRuntime.Reporter {
    private final Context context;private String action="upload",phase="preparing";private int percent=0;private long selectedBytes=0;
    public TransferWorker(@NonNull Context context,@NonNull WorkerParameters parameters){super(context,parameters);this.context=context.getApplicationContext();}
    private void check()throws InterruptedIOException{if(isStopped()||Thread.currentThread().isInterrupted())throw new InterruptedIOException("Transfer interrupted; original retained.");}
    @NonNull @Override public Result doWork(){
        try{String subject=getInputData().getString("subject"),workspace=getInputData().getString("workspace");action=getInputData().getString("action");CloudApi.workspace(workspace);JSONObject config=DeviceVault.configuration(context,subject,workspace);setForegroundAsync(foreground("Preparing encrypted transfer")).get(30,TimeUnit.SECONDS);CryptoRuntime.module(context);File stage=new File(context.getFilesDir(),"redx-jobs/"+getId());if(!stage.isDirectory()&&!stage.mkdirs())throw new IOException("Private transfer preparation unavailable.");android.system.Os.chmod(stage.getPath(),0700);String result;
            if("upload".equals(action)){JSONObject state=new CloudApi(context,subject).get("/v1/receivers/me");JSONObject note=null;JSONArray notes=state.getJSONArray("workspaces");for(int n=0;n<notes.length();n++)if(workspace.equals(notes.getJSONObject(n).optString("id")))note=notes.getJSONObject(n);if(note==null||!note.optBoolean("active")||note.optBoolean("readOnly"))throw new IOException("The MachineNote is read only; an active storage subscription is required.");Uri uri=Uri.parse(getInputData().getString("uri"));if(!"content".equals(uri.getScheme()))throw new IOException("Choose an item with the Android document picker.");File sources=new File(stage,"selection-"+java.util.UUID.randomUUID());if(!sources.mkdir())throw new IOException("Private selection directory unavailable.");DocumentFile selected=getInputData().getBoolean("folder",false)?DocumentFile.fromTreeUri(context,uri):DocumentFile.fromSingleUri(context,uri);if(selected==null||selected.getName()==null)throw new IOException("Selected document permission is unavailable.");File source=copy(selected,sources,0,new int[]{0});check();result=CryptoRuntime.module(context).callAttr("upload",config.toString(),source.getCanonicalPath(),stage.getCanonicalPath(),new CryptoRuntime.Auth(context,subject),this).toString();
            }else if("download".equals(action)){JSONObject item=new JSONObject(getInputData().getString("item"));if(!workspace.equals(item.optString("workspace")))throw new IOException("The selected item belongs to another MachineNote.");result=CryptoRuntime.module(context).callAttr("download",config.toString(),item.toString(),stage.getCanonicalPath(),new CryptoRuntime.Auth(context,subject),this).toString();}else throw new IOException("Unsupported encrypted transfer action.");
            check();JSONObject value=new JSONObject(result);if(!value.optBoolean("verified"))throw new IOException("Full encrypted readback did not verify.");if("upload".equals(action))try{clearPrepared(stage);}catch(Exception ignored){/* Verified cloud backup stays successful if private cache cleanup is deferred. */}percent=100;phase="complete";setProgressAsync(new Data.Builder().putInt("percent",100).putString("phase","complete").putString("message","Succeeded · verified; original retained").build()).get(10,TimeUnit.SECONDS);return Result.success(new Data.Builder().putString("action",action).putString("subject",subject).putString("path",value.optString("path","")).putString("name",value.optString("name","")).putBoolean("archiveExport",value.optBoolean("archiveExport")).putString("message","Succeeded · fully verified; original retained").build());
        }catch(Exception error){return Result.failure(new Data.Builder().putString("message",friendly(error)).putString("code","encrypted_transfer_failed").build());}
    }
    private void clearPrepared(File directory)throws Exception{File root=new File(context.getFilesDir(),"redx-jobs").getCanonicalFile();File actual=directory.getCanonicalFile();if(!actual.getParentFile().equals(root)||!actual.getName().equals(getId().toString()))throw new IOException("Private cleanup scope mismatch.");java.nio.file.Files.walkFileTree(actual.toPath(),new java.nio.file.SimpleFileVisitor<java.nio.file.Path>(){public java.nio.file.FileVisitResult visitFile(java.nio.file.Path path,java.nio.file.attribute.BasicFileAttributes attributes)throws IOException{java.nio.file.Files.delete(path);return java.nio.file.FileVisitResult.CONTINUE;}public java.nio.file.FileVisitResult postVisitDirectory(java.nio.file.Path path,IOException error)throws IOException{if(error!=null)throw error;java.nio.file.Files.delete(path);return java.nio.file.FileVisitResult.CONTINUE;}});}
    private File copy(DocumentFile document,File parent,int depth,int[] count)throws Exception{check();if(depth>100||++count[0]>100000)throw new IOException("The selected folder exceeds Android's bounded preparation limit.");String name=document.getName();if(name==null||TextChecks.isBlank(name)||name.equals(".")||name.equals("..")||name.contains("/")||name.contains("\\")||name.indexOf('\0')>=0||name.length()>255)throw new IOException("Selected item name is unsupported.");File target=new File(parent,name);if(target.exists())throw new IOException("Duplicate selected item name rejected.");if(document.isDirectory()){if(!target.mkdir())throw new IOException("Private folder preparation failed.");android.system.Os.chmod(target.getPath(),0700);Set<String> names=new HashSet<>();for(DocumentFile child:document.listFiles()){String childName=child.getName();if(childName==null||!names.add(java.text.Normalizer.normalize(childName,java.text.Normalizer.Form.NFC).toLowerCase(Locale.ROOT)))throw new IOException("The selected folder contains colliding names.");copy(child,target,depth+1,count);}}else if(document.isFile()){try(InputStream input=context.getContentResolver().openInputStream(document.getUri());FileOutputStream output=new FileOutputStream(target)){if(input==null)throw new IOException("Selected document is unavailable.");byte[] buffer=new byte[65536];int n;while((n=input.read(buffer))!=-1){check();if(parent.getUsableSpace()<10L*1024*1024*1024+n)throw new IOException("Keep at least 10 GiB free for encrypted preparation and verified readback.");output.write(buffer,0,n);selectedBytes+=n;setProgressAsync(new Data.Builder().putString("phase","preparing").putLong("done",selectedBytes).putString("message","Preparing selected owner files · "+selectedBytes+" bytes").putInt("percent",0).build());}output.getFD().sync();}android.system.Os.chmod(target.getPath(),0600);}else throw new IOException("Unsupported selected document type.");return target;}
    @Override public synchronized void report(String json){if(isStopped())return;try{JSONObject state=new JSONObject(json);String next=state.optString("phase","preparing");long done=Math.max(0,state.optLong("completed_bytes")),total=Math.max(0,state.optLong("total_bytes"));double fraction=total>0?Math.min(1,(double)done/total):0;int observed;if("download".equals(action))observed=next.equals("readback")||next.equals("decoding")?(int)(90*fraction):next.equals("verifying")?95:next.equals("complete")?99:0;else observed=switch(next){case "archiving"->10+(int)(5*fraction);case "encoding","uploading"->15+(int)(50*fraction);case "publishing"->65;case "readback","decoding"->65+(int)(30*fraction);case "verifying"->95;case "complete"->99;default->0;};percent=Math.max(percent,Math.min(99,observed));phase=next;String message=next+" · "+percent+"% · "+done+" / "+total+" phase bytes";setProgressAsync(new Data.Builder().putInt("percent",percent).putString("phase",next).putLong("done",done).putLong("total",total).putLong("uploaded",state.optLong("uploaded_bytes")).putLong("downloaded",state.optLong("downloaded_bytes")).putLong("objectsDone",state.optLong("objects_done")).putLong("objectsTotal",state.optLong("objects_total")).putString("message",message).build());setForegroundAsync(foreground(message));}catch(Exception ignored){/* Best effort display; no credential logging. */}}
    private ForegroundInfo foreground(String message){String channel="gendragoon-redx-encrypted";NotificationManager manager=(NotificationManager)context.getSystemService(Context.NOTIFICATION_SERVICE);manager.createNotificationChannel(new NotificationChannel(channel,"Encrypted transfers",NotificationManager.IMPORTANCE_LOW));Notification notification=new NotificationCompat.Builder(context,channel).setSmallIcon(R.drawable.ic_cloud).setContentTitle("GenDragoon MachineNotes").setContentText(message).setOnlyAlertOnce(true).setOngoing(true).setProgress(100,percent,false).build();return new ForegroundInfo(6143,notification,ServiceInfo.FOREGROUND_SERVICE_TYPE_DATA_SYNC);}
    private static String friendly(Exception error){String value=String.valueOf(error.getMessage()).toLowerCase(Locale.ROOT);if(value.contains("vault")||value.contains("autherror")||value.contains("authentication"))return "This device needs the compatible private vault to unlock this backup. Sign-in alone cannot recover lost encryption keys. Originals and cloud data were retained.";if(value.contains("10 gib")||value.contains("space"))return "Keep 10 GiB free plus preparation and verified readback space. Original retained.";if(value.contains("read only")||value.contains("quota")||value.contains("507"))return "The MachineNote is read only or its storage quota is full. Check its plan in GenDragoon. Original retained.";if(value.contains("session")||value.contains("401")||value.contains("account changed"))return "Reconnect the intended Red-XAI account before resuming. Original retained.";if(value.contains("collision")||value.contains("409"))return "A same-name item or another operation conflicts with this upload. Existing backups and the original were retained.";if(value.contains("unreachable")||value.contains("timeout")||value.contains("network"))return "The connection was interrupted. Verified cloud chunks remain available for a retry; original retained.";return "The encrypted transfer did not finish verification. The original and retained job data were kept. Review storage, connection and device keys before retrying.";}
}
